package com.enterpriseweb.portal.controller;

import com.enterpriseweb.portal.client.ThemeAssetFeignClient;
import com.enterpriseweb.portal.security.WorkspacePrincipal;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/ui")
public class ThemeProxyController {

    private final ThemeAssetFeignClient themeClient;

    public ThemeProxyController(ThemeAssetFeignClient themeClient) {
        this.themeClient = themeClient;
    }

    @GetMapping(value = "/theme-bundle", produces = "text/css")
    public ResponseEntity<String> getWorkspaceThemeCss(
            @AuthenticationPrincipal WorkspacePrincipal principal) {
        String verifiedWorkspace = principal.getDefaultWorkspaceId();
        String cssContent = themeClient.getWorkspaceBundle(verifiedWorkspace);
        return ResponseEntity.ok()
                .contentType(MediaType.valueOf("text/css"))
                .body(cssContent);
    }
}
